export {
  resolveDisplayCnyFromVenueUsdc,
  resolvePlanCnyFromVenueOrder,
  resolvePlanCnyFromVenueStake,
  resolveVenueStakeFromPlanCny,
  type ResolveVenueStakeOpts,
} from "./a8VenueMoney";
export {
  isA8VenueReject,
  resolveA8VenueLegOutcome,
  withA8ResolveLegOutcome,
} from "./a8LegOutcome";

/** @deprecated 见 extensionsMode.ts */
export {
  isPbChangmenExtensions,
  isPbLiveFoOnly,
  isPbPrematchCollectEnabled,
  setPbChangmenExtensions,
  setPbLiveFoOnly,
} from "./extensionsMode";

/** [changmen 扩展] 轻量偏好入口；不加载订单簿、签名器或平台 registry。 */
export { getPmFokPreflightMode, onPmFokPreflightModeChange, setPmFokPreflightMode,
  capturePmFokPreflightMode } from "./submission/preflight/pmFokPreflightMode";

/** [changmen 扩展] 无全局单例、无预检/签名/提交依赖。服务管理簿生命周期；消费者仅管理读取租约，不管理 PM-M 订阅。 */
export { BOOK_LIMITS, decimal, numericAsks, reduceBookFrame } from "./bookReducer";
export type { LocalOrderBook, ReducedFrame } from "./bookReducer";
export { PassiveBookFeed } from "./passiveBookFeed";
export type { BookFeed, BookFeedOptions } from "./feedTypes";

/** [changmen 扩展] 动态 FOK 旁路消费者入口；订单簿核心独立位于 realtime/orderBook。 */
export { WsBookShadowRuntime, officialGateway } from "../browser/pm-book-diagnostics/bookRuntime";
export { WsBookShadowWorkerClient } from "../browser/pm-book-diagnostics/shadowWorkerClient";

export * from "./checkBetProbe";
export * from "./directRealtimeStatus";
export * from "@changmen/venue-browser/shared/venueWsStatus";
export * from "./rejectWait";
export * from "@changmen/venue-browser/shared/webBridge";
export * from "@changmen/venue-browser/shared/webBridgeTypes";
export * from "@changmen/venue-browser/shared/changmenAuthToken";
export * from "@changmen/venue-browser/shared/changmenWsBase";
export * from "./socket/changmenHub";
export { PLATFORMS } from "@changmen/client-core/shared/platforms";

